// sites.h - every place TODGameplay.dll patches in the GOG TOD.exe (md5 d9beb351b3c78ee9f14a766a368f3ff9), with the
// shipped bytes it checks first. The DLL patches a site only when ALL its bytes match (and the feature is on); a site
// that does not match is skipped and logged. tests/dll/check_sites.py parses this file and checks every row against the
// exe on disk (read only), and that each patch covers whole instructions.
//
// SITE(id, feature, check_va, "shipped bytes from check_va", patch_offset, patch_len, kind, "what")
//   kind CALL  = the 5-byte call rel32 at check_va+patch_offset is retargeted (its original target is in the bytes)
//        JMP   = patch_len bytes at check_va+patch_offset become jmp rel32 (+ nop); the stub re-executes them
//        OPER  = patch_len bytes at check_va+patch_offset are replaced (operand / addressing change)
// REF(id, check_va, "bytes", "why") = code that proves a game address or member offset the DLL reads/writes is what we
//   think it is (checked here and at run time before the feature that relies on it is enabled; never patched).
#ifndef SITE
#define SITE(id, feature, va, hex, off, len, kind, what)
#endif
#ifndef REF
#define REF(id, va, hex, why)
#endif

